args.query:
SELECT COUNT(*) as total_original FROM measurements;
SELECT COUNT(*) as total_cleaned FROM cleaned_measurements;
SELECT 'Outliers removed' as status, 
    (SELECT COUNT(*) FROM measurements) - (SELECT COUNT(*) FROM cleaned_measurements) as rows_removed
FROM cleaned_measurements;

SELECT 'Original' as table_name, COUNT(*) as rows FROM measurements
UNION ALL
SELECT 'Cleaned' as table_name, COUNT(*) as rows FROM cleaned_measurements;
